package com.schooloss.fullnative.feature.gallery;
import android.os.Bundle;import android.view.*;import android.widget.*;import com.schooloss.fullnative.core.*;import org.json.*;
public final class GalleryAlbumActivity extends BaseActivity {
 private int id;@Override protected void onCreate(Bundle b){super.onCreate(b);id=getIntent().getIntExtra("id",0);loading("Opening gallery","Loading private school album…");load();}
 private void load(){io.execute(()->{try{JSONObject r=api.get("gallery_album","id="+id);JSONObject d=r.optJSONObject("data");runOnUiThread(()->render(d));}catch(Exception e){runOnUiThread(()->error("Could not open album",e,this::load));}});}
 private void render(JSONObject d){LinearLayout p=Ui.v(this);p.setPadding(Ui.dp(this,14),Ui.dp(this,12),Ui.dp(this,14),Ui.dp(this,24));p.setBackgroundColor(Constants.BG);TextView back=Ui.text(this,"‹  Gallery",12,Constants.BLUE,true);back.setOnClickListener(v->finish());p.addView(back);p.addView(Ui.text(this,d==null?"Album":d.optString("title","Album"),23,Constants.TEXT,true));if(d!=null)p.addView(Ui.text(this,d.optString("description",""),11,Constants.MUTED,false));JSONArray m=d==null?null:d.optJSONArray("media");if(m!=null)for(int i=0;i<m.length();i++){JSONObject x=m.optJSONObject(i);com.google.android.material.card.MaterialCardView c=Ui.card(this);LinearLayout in=Ui.v(this);in.setPadding(Ui.dp(this,12),Ui.dp(this,10),Ui.dp(this,12),Ui.dp(this,10));in.addView(Ui.text(this,Ui.pretty(x.optString("media_type","media"))+" #"+x.optInt("id"),13,Constants.TEXT,true));in.addView(Ui.text(this,x.optString("mime_type","")+" · "+x.optLong("file_size",0)+" bytes",9,Constants.MUTED,false));c.addView(in);LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT,ViewGroup.LayoutParams.WRAP_CONTENT);lp.topMargin=Ui.dp(this,7);p.addView(c,lp);}ScrollView s=new ScrollView(this);s.addView(p);setContentView(s);}
}